package com.cpf.starter.grpc;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.integration.grpc") public class CpfGrpcProperties {private boolean enabled;private String target;private boolean plaintext;private Duration deadline=Duration.ofSeconds(5);private int maxInboundBytes=4194304,maxPending=1000;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getTarget(){return target;}public void setTarget(String v){target=v;}public boolean isPlaintext(){return plaintext;}public void setPlaintext(boolean v){plaintext=v;}public Duration getDeadline(){return deadline;}public void setDeadline(Duration v){deadline=v;}public int getMaxInboundBytes(){return maxInboundBytes;}public void setMaxInboundBytes(int v){maxInboundBytes=v;}public int getMaxPending(){return maxPending;}public void setMaxPending(int v){maxPending=v;}public void validate(){if(!enabled)return;if(target==null||target.isBlank()||deadline.isZero()||deadline.isNegative()||maxInboundBytes<1||maxPending<1)throw new IllegalStateException("gRPC target/deadline/limits required");}}
